import { DealEntity } from './deal.entity';

export const DEAL_STAGE_VALUES = [
  'lead',
  'qualified',
  'active',
  'negotiation',
  'closed_won',
  'closed_lost',
] as const;

export type DealStage = (typeof DEAL_STAGE_VALUES)[number];

export const DEAL_INITIAL_STAGE_VALUES = ['lead', 'qualified'] as const;

export type DealInitialStage = (typeof DEAL_INITIAL_STAGE_VALUES)[number];

const DEAL_STAGE_SET = new Set<string>(DEAL_STAGE_VALUES);
const DEAL_INITIAL_STAGE_SET = new Set<string>(DEAL_INITIAL_STAGE_VALUES);

const DEAL_STAGE_TRANSITIONS: Record<DealStage, DealStage[]> = {
  lead: ['qualified', 'closed_lost'],
  qualified: ['active', 'closed_lost'],
  active: ['negotiation', 'closed_lost'],
  negotiation: ['closed_won', 'closed_lost'],
  closed_won: [],
  closed_lost: ['lead'],
};

export function isDealStage(value: string): value is DealStage {
  return DEAL_STAGE_SET.has(value);
}

export function isDealInitialStage(value: string): value is DealInitialStage {
  return DEAL_INITIAL_STAGE_SET.has(value);
}

export function parseRequestedDealStage(
  value: string | null | undefined,
): DealStage | null {
  if (typeof value !== 'string') {
    return null;
  }

  return isDealStage(value) ? value : null;
}

export function normalizeStoredDealStage(
  value: DealEntity['stage'] | null | undefined,
): DealStage {
  if (typeof value !== 'string') {
    return 'lead';
  }

  const normalized = value.trim().toLowerCase();

  if (isDealStage(normalized)) {
    return normalized;
  }

  if (normalized === 'won') {
    return 'closed_won';
  }

  if (normalized === 'lost') {
    return 'closed_lost';
  }

  if (normalized === 'prospect') {
    return 'lead';
  }

  if (normalized === 'proposal_sent') {
    return 'negotiation';
  }

  return 'lead';
}

export function isStageTransitionAllowed(
  currentStage: DealStage,
  targetStage: DealStage,
) {
  return DEAL_STAGE_TRANSITIONS[currentStage].includes(targetStage);
}

export function getStageTransitionTargets(stage: DealStage): DealStage[] {
  return [...DEAL_STAGE_TRANSITIONS[stage]];
}
