const DEAL_STAGE_SET = new Set(DEAL_STAGES);

const TRANSITION_TARGETS = {
  lead: ['qualified', 'closed_lost'],
  qualified: ['active', 'closed_lost'],
  active: ['negotiation', 'closed_lost'],
  negotiation: ['closed_won', 'closed_lost'],
  closed_won: [],
  closed_lost: ['lead'],
};

export function normalizeDealStage(stage) {
  return DEAL_STAGE_SET.has(stage) ? stage : 'lead';
}

export function formatDealStageLabel(stage) {
  return stage
    .split('_')
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join(' ');
}

export function getStageOptionsForEdit(currentStage, { hasLinkedContacts }) {
  const normalizedCurrentStage = normalizeDealStage(currentStage);
  const allowedTransitions = TRANSITION_TARGETS[normalizedCurrentStage] ?? [];
  const nextOptions = [normalizedCurrentStage, ...allowedTransitions].filter(
    (stage, index, list) => list.indexOf(stage) === index,
  );

  return nextOptions.filter(
    (stage) => stage !== 'active' || hasLinkedContacts || stage === normalizedCurrentStage,
  );
}

export function isTerminalWonStage(stage) {
  return normalizeDealStage(stage) === 'closed_won';
}
