    18	  async findWithFilter(query: DealListQueryDto) {
    19	    const page = query.page ?? 1;
    20	    const pageSize = query.pageSize ?? 10;
    21	
    22	    const queryBuilder = this.createQueryBuilder('deal');
    23	
    24	    if (query.stage) {
    25	      queryBuilder.andWhere('deal.stage = :stage', { stage: query.stage });
    26	    }
    27	
    28	    if (query.companyId) {
    29	      queryBuilder.andWhere('deal.companyId = :companyId', {
    30	        companyId: query.companyId,
    31	      });
    32	    }
    33	
    34	    const [items, total] = await queryBuilder
    35	      .orderBy('deal.createdAt', 'DESC')
    36	      .skip((page - 1) * pageSize)
    37	      .take(pageSize)
    38	      .getManyAndCount();
    39	
    40	    return {
    41	      items,
    42	      total,
    43	      page,
    44	      pageSize,
    45	      totalPages: total === 0 ? 0 : Math.ceil(total / pageSize),
    46	    };
    47	  }
