    49	  async findContactLinksByDealIds(dealIds: string[]) {
    50	    if (dealIds.length === 0) {
    51	      return new Map<string, DealContactLinkSummary[]>();
    52	    }
    53	
    54	    const rows = await this.dataSource
    55	      .createQueryBuilder()
    56	      .select('link."dealId"', 'dealId')
    57	      .addSelect('link."contactId"', 'contactId')
    58	      .addSelect('link."role"', 'role')
    59	      .from('deal_contact_links', 'link')
    60	      .where('link."dealId" IN (:...dealIds)', { dealIds })
    61	      .orderBy('link."dealId"', 'ASC')
    62	      .getRawMany<{
